package com.marketlabs.pulse.ui.common

// Generated by Claude Code.

import retrofit2.HttpException
import java.io.IOException

/**
 * Shared error classification for ViewModel UiStates. Every screen up to this one has used a
 * flat `errorMessage: String?` instead -- this is the first adopter of a typed split, added for
 * the Stock Analysis feature so the (future) Screen can distinguish "no connection" from "server
 * rejected the request" from "something else went wrong" rather than only having a pre-formatted
 * string to show as-is. `message` stays available on every variant so a ViewModel can still carry
 * the underlying exception's text through for a Snackbar/retry copy without every call site having
 * to branch on the sealed type just to get something to display.
 */
sealed class UiError(val message: String?) {
    class Network(message: String? = null) : UiError(message)
    class Server(message: String? = null) : UiError(message)
    class Unknown(message: String? = null) : UiError(message)
}

/**
 * `IOException` covers no-connection/timeout (`SocketTimeoutException`, `UnknownHostException`,
 * etc. are all subtypes); a thrown `HttpException` means a response came back but Retrofit's
 * non-2xx check rejected it, i.e. the server responded but with an error status. Anything else
 * (a Moshi parse failure, a null-pointer in a mapper) doesn't cleanly fit either bucket. Shared
 * between StockAnalysisViewModel and StockDetailViewModel rather than duplicated in each.
 */
fun Throwable?.toUiError(): UiError = when (this) {
    is IOException -> UiError.Network(localizedMessage)
    is HttpException -> UiError.Server(localizedMessage)
    else -> UiError.Unknown(this?.localizedMessage)
}
